<template><fieldset class="translation-field"><legend>{{label}}</legend><p><strong>Source</strong></p><p class="translation-field__source">{{field.source}}</p><p><strong>Translation</strong> <span v-if="field.state==='UNTRANSLATED'">Untranslated</span></p><textarea v-if="multiline" v-model="value" :aria-label="`${label} translation`" @input="emitValue"/><BtgTextInput v-else v-model="value" :aria-label="`${label} translation`" @input="emitValue"/><BtgButton type="button" variant="secondary" @click="markUntranslated">Mark as untranslated</BtgButton></fieldset></template>
<script setup lang="ts">import{ref,watch}from'vue';import BtgButton from'./BtgButton.vue';import BtgTextInput from'./BtgTextInput.vue';import type{TextField}from'../translations/translations';const props=defineProps<{label:string;field:TextField;multiline?:boolean}>(),emit=defineEmits<{change:[value:string|null]}>();const value=ref(props.field.translated??'');watch(()=>props.field,(next)=>value.value=next.translated??'');function emitValue(){emit('change',value.value)}function markUntranslated(){value.value='';emit('change',null)}</script>
